using ghidra.util.task;

public class EmbeddedMediaAnalyzer : AbstractAnalyzer {
	private static readonly string NAME = "Embedded Media";
	private static readonly string DESCRIPTION =
		"Finds embedded media data types (e.g., png, gif, jpeg, wav)";

	private static readonly string OPTION_NAME_CREATE_BOOKMARKS = "Create Analysis Bookmarks";
	private static readonly string OPTION_DESCRIPTION_CREATE_BOOKMARKS =
		"If checked, an analysis bookmark will be created at each location where embedded media " +
			"data is identified.";
	private static readonly bool OPTION_DEFAULT_CREATE_BOOKMARKS_ENABLED = true;

	private bool createBookmarksEnabled = OPTION_DEFAULT_CREATE_BOOKMARKS_ENABLED;

	public EmbeddedMediaAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER)
    {
		setDefaultEnablement(true);
		setPriority(AnalysisPriority.BLOCK_ANALYSIS);
		setSupportsOneTimeAnalysis();
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		Memory memory = program.getMemory();
		AddressSetView validMemorySet = memory.getLoadedAndInitializedAddressSet();
		AddressSetView searchSet = set.intersect(validMemorySet);
		if (searchSet.isEmpty()) {
			return false;  // no valid addresses to search
		}

		MemoryBytePatternSearcher searcher = new MemoryBytePatternSearcher("Embedded Media");

		List<Address> foundMedia = new();

		addByteSearchPattern(searcher, program, foundMedia, new GifDataType(), "GIF 87",
			GifDataType.MAGIC_87, GifDataType.GIFMASK);

		addByteSearchPattern(searcher, program, foundMedia, new GifDataType(), "GIF 89",
			GifDataType.MAGIC_89, GifDataType.GIFMASK);

		addByteSearchPattern(searcher, program, foundMedia, new PngDataType(), "PNG",
			PngDataType.MAGIC, PngDataType.MASK);

		addByteSearchPattern(searcher, program, foundMedia, new JPEGDataType(), "JPEG",
			JPEGDataType.MAGIC, JPEGDataType.MAGIC_MASK);

		addByteSearchPattern(searcher, program, foundMedia, new WAVEDataType(), "WAVE",
			WAVEDataType.MAGIC, WAVEDataType.MAGIC_MASK);

		addByteSearchPattern(searcher, program, foundMedia, new MIDIDataType(), "MIDI",
			MIDIDataType.MAGIC, MIDIDataType.MAGIC_MASK);

		addByteSearchPattern(searcher, program, foundMedia, new AUDataType(), "AU",
			AUDataType.MAGIC, AUDataType.MAGIC_MASK);

		addByteSearchPattern(searcher, program, foundMedia, new AIFFDataType(), "AIFF",
			AIFFDataType.MAGIC_AIFF, AIFFDataType.MAGIC_MASK);

		addByteSearchPattern(searcher, program, foundMedia, new AIFFDataType(), "AIFC",
			AIFFDataType.MAGIC_AIFC, AIFFDataType.MAGIC_MASK);

		searcher.search(program, searchSet, monitor);

		return foundMedia.size() > 0;
	}

	private void addByteSearchPattern(MemoryBytePatternSearcher searcher, Program program,
			List<Address> foundMedia, DataType mediaDT, string mediaName, byte[] bytes,
			byte[] mask) {

		if (bytes == null) {
			return;
		}

		GenericMatchAction<DataType> action = new _Anon_GenericMatchAction_DataType_1(mediaDT);

		GenericByteSequencePattern<DataType> pattern =
			new(bytes, mask, action);
		searcher.addPattern(pattern);
	}

	/* @Override */
	public void registerOptions(Options options, Program program) {
		options.registerOption(OPTION_NAME_CREATE_BOOKMARKS, createBookmarksEnabled, null,
			OPTION_DESCRIPTION_CREATE_BOOKMARKS);

	}

	/* @Override */
	public void optionsChanged(Options options, Program program) {
		createBookmarksEnabled =
			options.getBoolean(OPTION_NAME_CREATE_BOOKMARKS, createBookmarksEnabled);
	}

	internal class _Anon_GenericMatchAction_DataType_1 : GenericMatchAction<DataType>
	{
		public _Anon_GenericMatchAction_DataType_1() : @base(mediaDT) {}


			/* @Override */
			public void apply(Program prog, Address addr, Match<Pattern> match) {
				// See if it is already an applied media data type
				if (!program.getListing().isUndefined(addr, addr)) {
					return;
				}

				try {
					CreateDataCmd cmd = new CreateDataCmd(addr, mediaDT);
					if (cmd.applyTo(program)) {
						if (createBookmarksEnabled) {
							program.getBookmarkManager()
									.setBookmark(addr, BookmarkType.ANALYSIS,
										"Embedded Media", "Found " + mediaName + " Embedded Media");
						}
						foundMedia.add(addr);
					}

					// If media does not apply correctly then it is not really that media data type 
					// or there is other data in the way.
				}
				catch (Exception e) {
					// Not a valid embedded media or no room to apply it so just ignore it and skip

				}
			}
		
	}

}
